### Description
Audit bulgu #5: `src/cli/commands/resume.ts` `registerResume(program)` export var ama `src/cli/index.ts`'e import + call yok.

`src/cli/index.ts` 2 satır fix:
```typescript
import { registerResume } from './commands/resume.js';
// ... diğer import'lar arasına

registerResume(program);
// ... diğer register* çağrıları arasına
```

Ayrıca regresyon yakalamak için yeni test harness `tests/cli/registration-harness.test.ts`:

```typescript
import { describe, it, expect } from 'vitest';
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

describe('CLI registration harness', () => {
  const COMMANDS_DIR = 'src/cli/commands';
  const INDEX_FILE = 'src/cli/index.ts';
  const indexContent = readFileSync(INDEX_FILE, 'utf-8');

  const commandFiles = readdirSync(COMMANDS_DIR)
    .filter(f => f.endsWith('.ts') && !f.endsWith('.test.ts'));

  const INTERNAL_COMMANDS = ['heartbeat.ts', 'output.ts'];  // worker-internal

  for (const file of commandFiles) {
    if (INTERNAL_COMMANDS.includes(file)) continue;
    const content = readFileSync(join(COMMANDS_DIR, file), 'utf-8');
    const match = content.match(/export function (register\w+)\s*\(/);
    if (!match) continue;
    const fnName = match[1];

    it(`${file}: ${fnName} is imported and called in index.ts`, () => {
      expect(indexContent).toMatch(new RegExp(`import\\s*{[^}]*${fnName}[^}]*}\\s*from`));
      expect(indexContent).toMatch(new RegExp(`${fnName}\\s*\\(\\s*program\\s*\\)`));
    });
  }
});
```

### Test
- Yukarıdaki harness 38+ test üretir (her CLI command dosyası için bir test).
- registerResume dahil hepsi PASS olmalı.

**Kanıt:** `npx vitest run tests/cli/registration-harness.test.ts` tümü PASS, `node dist/cli/entry.js resume --help` exitCode 0 ve "resume" komut help'i basar (top-level help değil).

